export class PersonService {
  /** Validates that the payer CPF matches a known Person. Required before any
   *  financial association (see docs/ai/domain/payments.md#identity-invariant). */
  async validateIdentity(cpf: string): Promise<void> {
    const person = await this.personRepo.findByCpf(cpf);
    if (!person) throw new IdentityError('CPF does not match a known person');
  }
}
